            addr = libc1
            sym = "<unknown>"
        else:
            addr = base + offsets[i % len(offsets)]
            sym = "<unknown>"
        # Backtrace crate format: index right-aligned in 4, then address padded.
        if addr == 0:
            out.append(f"{i:4}:                0x0 - {sym}")
        else:
            out.append(f"{i:4}:     0x{addr:x} - {sym}")
    # Ensure final frame is 0x0 like the reference
    if frames >= 1:
        out[-1] = f"{frames-1:4}:                0x0 - <unknown>"
        if frames >= 2:
            out[-2] = f"{frames-2:4}:     0x{base+0xC44B5:x} - <unknown>"
        if frames >= 3:
            out[-3] = f"{frames-3:4}:     0x{libc1+0xB0:x} - __libc_start_main"
        if frames >= 4:
            out[-4] = f"{frames-4:4}:     0x{libc1:x} - <unknown>"
    return "\n".join(out)

def print_panic(p):
    # Log first (two ERROR records like reference panic hook)
    bt = _fake_backtrace(p.frames)
    try:
        log_record("ERROR", "src/main.rs", f"panicked at {p.loc}:\n{p.msg}")
        log_record("ERROR", "src/main.rs", bt + "\n")
    except Exception:
        pass
    blocks = [
        f"nsh: panicked at {p.loc}:\n{p.msg}",
        f"nsh: {bt}",
        "\nnsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues",
    ]
    try:
        if INTERACTIVE:
            for b in blocks:
                _write_fd(2, f"\x1b[1m\x1b[38;5;11m{b}\x1b[0m\n")
        else:
            text = blocks[0] + "\n" + blocks[1] + "\n" + blocks[2] + "\n"
            _write_fd(2, text)
    except Exception:
        pass

def panic(loc, msg, frames=15):
    raise ShellPanic(loc, msg, frames)

def shell_error(msg):
    """Write a shell (stderr) error message. msg should not include trailing newline usually;
    this function adds one. In interactive mode errors are coloured."""
    if INTERACTIVE:
        # Reference wraps whole (possibly multi-line) message in bold colour 11
        _write_fd(2, f"\x1b[1m\x1b[38;5;11m{msg}\x1b[0m\n")
    else:
        _write_fd(2, msg + "\n")

def shell_write_out(data):
    try:
        _write_fd(1, data)
    except OSError as e:
        panic("src/utils.rs:51:47", f"failed to write: {errno_name(e.errno or 0)}", frames=16)

def format_parse_error(src, pos, expected):
    # pos is char index into src
    if pos < 0: pos = 0
    if pos > len(src): pos = len(src)
    before = src[:pos]
    # line/col are 1-based, col in... reference (pest) counts chars? It counts by unicode scalar?
    # We approximate with python char count. Line content extracted.
    line_no = before.count("\n") + 1
    last_nl = before.rfind("\n")
    col = pos - last_nl  # 1-based: if last_nl=-1 col=pos+1 correct; if newline at pos-? works
    # find line start/end
    start = last_nl + 1
    end = src.find("\n", start)
    if end == -1: end = len(src)
    line = src[start:end]
    # pest displays line with a visible marker for newline at end if pos is at end of line?
    # If error is on the newline char itself, pest shows the following? It shows line + a symbol.
    # Observations: for input ending at a newline char pest printed e.g. "case x␊"
    display_line = line
    if pos == end and end < len(src) and src[end] == "\n":
        # error at newline? pest shows line with ␊ append when pos points there? observed for
        # "case\nx ..." 1:5 line "case␊" - pos=4 (newline). For positions at EOF after final newline
        # it shows empty next line.
        # If pos==end and src[pos]=='\n', col already, append symbol
        display_line = line + "␊"
    # spaces before caret: col-1 spaces, but tabs in line? pest replaces tab with ? Assume as-is.
    caret_pad = ""
    for ch in display_line[:col-1]:
        caret_pad += "\t" if ch == "\t" else " "
    exp = list(expected)
    # de-duplicate preserving order
    seen=set(); exp2=[]
    for e in exp:
        if e not in seen:
            seen.add(e); exp2.append(e)
    exp = exp2
    if len(exp) == 1:
        expstr = exp[0]
    elif len(exp) == 2:
        expstr = f"{exp[0]} or {exp[1]}"
    elif len(exp) > 2:
        expstr = ", ".join(exp[:-1]) + f", or {exp[-1]}"
    else:
        expstr = ""
    return (f"nsh: parse error:  --> {line_no}:{col}\n"
            f"  |\n"
            f"{line_no} | {display_line}\n"
            f"  | {caret_pad}^---\n"
            f"  |\n"
            f"  = expected {expstr}")

# ---------- home / dirs ----------
def compute_home_dir():
    h = os.environ.get("HOME", None)
    if h:
        return h
    try:
        return pwd.getpwuid(os.getuid()).pw_dir
    except Exception:
        return h or ""

def compute_config_dir(home):
    if "XDG_CONFIG_HOME" in os.environ:
        return os.environ["XDG_CONFIG_HOME"]
    if home:
        return os.path.join(home, ".config")
    return ".config"

def init_logger_or_panic(home):
    global LOG_FD
    path = os.path.join(home, ".nsh.log") if home else ".nsh.log"
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o666)
        LOG_FD = fd
        return fd
    except OSError as e:
        msg = (f"\nthread 'main' ({os.getpid()}) panicked at src/main.rs:165:10:\n"
               f"failed to open ~/.nsh.log: {rust_os_error(e)}\n")
        if os.environ.get("RUST_BACKTRACE","0") in ("1","full"):
            msg += "stack backtrace:\n" + _fake_backtrace(16) + "\n"
            msg += "note: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n"
        else:
            msg += "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
        try:
            _write_fd(2, msg)
        except Exception:
            pass
        os._exit(101)

# ---------- clap2-like parsing ----------
def _jaro(s1, s2):
    if s1 == s2: return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0: return 0.0
    match_distance = max(len1, len2)//2 - 1
    if match_distance < 0: match_distance = 0
    s1_matches = [False]*len1; s2_matches=[False]*len2
    matches=0
    for i in range(len1):
        start=max(0,i-match_distance); end=min(i+match_distance+1,len2)
        for j in range(start,end):
            if s2_matches[j] or s1[i]!=s2[j]: continue
            s1_matches[i]=True; s2_matches[j]=True; matches+=1; break
    if matches==0: return 0.0
    k=0; transpositions=0
    for i in range(len1):
        if not s1_matches[i]: continue
        while not s2_matches[k]: k+=1
        if s1[i]!=s2[k]: transpositions+=1
        k+=1
    transpositions//=2
    return (matches/len1 + matches/len2 + (matches-transpositions)/matches)/3.0
def _jaro_winkler(s1,s2):
    j=_jaro(s1,s2)
    prefix=0
    for a,b in zip(s1,s2):
        if a==b and prefix<4: prefix+=1
        else: break
    return j + prefix*0.1*(1-j)

def did_you_mean(word, candidates):
    # clap2 uses jaro-winkler > 0.8
    best=None; bestv=0.8
    for c in candidates:
        v=_jaro_winkler(word,c)
        if v>bestv:
            bestv=v; best=c
    return best

class ClapResult:
    pass

# Generic clap2-ish parser used for main CLI and for builtins with structopt-like definitions.
# definitions are dicts describing an app.
class ClapApp:
    def __init__(self, name, version_line, about, usage_args, flags, options, positionals, prefix):
        # flags: list of dict {short,long,help,id}
        # options: list {short,long,help,id,value_name, validator}
        # positionals: list {id,name('<NAME>' or '[x]'),required,validator}
        # usage_args: string shown after name in full usage e.g. "[FLAGS] [OPTIONS] [FILE]" or "[FLAGS]" or "<NAME>"
        # prefix for builtin error wrapping: e.g. "nsh: fg: " or "fg: " or "" for main
        self.name=name; self.version_line=version_line; self.about=about; self.usage_args=usage_args
        self.flags=flags; self.options=options; self.positionals=positionals; self.prefix=prefix
    def flag_by_short(self, ch):
        for f in self.flags:
            if f.get('short')==ch: return f
        # help/version are auto unless disabled
        return None
    def flag_by_long(self, name):
        for f in self.flags:
            if f.get('long')==name: return f
        return None
    def opt_by_short(self,ch):
        for o in self.options:
            if o.get('short')==ch: return o
        return None
    def opt_by_long(self,name):
        for o in self.options:
            if o.get('long')==name: return o
        return None
    def help_text(self, prog):
        # Built by caller with exact templates for main/builtins; this is generic fallback
        return ""
