MAIN_HELP_TEMPLATE = """nsh 0.4.2
A command-line shell that focuses on performance and productivity.

USAGE:
    {prog} [FLAGS] [OPTIONS] [FILE]

FLAGS:
    -h, --help       Prints help information
    -l, --login      Behave like a login shell
        --norc       Don't load nshrc
        --version    Print the version

OPTIONS:
    -c <command>        The command to be executed

ARGS:
    <FILE>    The file to be executed
"""

def _prog_name(argv0):
    if not argv0:
        return "nsh"
    # clap uses file name component of argv0 (basename), empty -> ?
    # If argv0 is a path, use basename. If it starts with '-', keep as-is basename.
    base = argv0.rstrip("/")
    if "/" in base:
        base = base.rsplit("/",1)[-1]
    return base if base else argv0

def _clap_suggestion_text(sug):
    # sug is long name without dashes
    return f"\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{sug}\x1b[0m?"

def parse_main_cli(argv):
    """Returns dict or exits process with clap behaviour (help/version/error). argv excludes prog."""
    prog = _prog_name(sys.argv[0] if sys.argv else "nsh")
    # Used args for smart usage in order: -c, --login, --norc, --version, --help (observed order)
    used = []  # list of ids in canonical order will be computed at error time
    used_set = set()
    def mark(id_):
        used_set.add(id_)
    def smart_usage(extra_id=None):
        ids = set(used_set)
        if extra_id: ids.add(extra_id)
        if not ids:
            return f"{prog} [FLAGS] [OPTIONS] [FILE]"
        parts=[]
        # order observed: -c first, then --help ? test suggest help alone shows --help only.
        # Canonical ordering guess based on definition order in struct: command, login, norc, version, help?
        order = [('c',"-c <command>"),('login',"--login"),('norc',"--norc"),('version',"--version"),('help',"--help")]
        for id_,txt in order:
            if id_ in ids: parts.append(txt)
        return f"{prog} " + " ".join(parts)
    def err_exit(msg, extra_id=None, suggestion=None):
        text = f"error: {msg}"
        if suggestion:
            text += _clap_suggestion_text(suggestion)
        text += f"\n\nUSAGE:\n    {smart_usage(extra_id or (('help' if suggestion=='help' else 'version' if suggestion=='version' else 'login' if suggestion=='login' else 'norc' if suggestion=='norc' else None)))}\n\nFor more information try --help\n"
        _write_fd(2, text)
        raise SystemExit(1)
    login=False; norc=False; version=False; command=None; file=None
    seen_counts={}
    def seen_once(id_, display):
        seen_counts[id_]=seen_counts.get(id_,0)+1
        # duplicate validation is deferred until after parsing, UNLESS no help present - handle later by recording
    deferred_dup = None  # (id, display)
    i=0; after_dd=False
    help_requested=False
    while i < len(argv):
        arg = argv[i]
        if after_dd:
            if file is not None:
                err_exit(f"Found argument '{arg}' which wasn't expected, or isn't valid in this context")
            file = arg; i+=1; continue
        if arg == "--":
            after_dd=True; i+=1; continue
        # Long flags: clap trims all leading dashes (---help works)
        if arg.startswith("--") and arg not in ("--",):
            raw = arg.lstrip("-")
            if "=" in raw:
                name, val = raw.split("=",1)
            else:
                name, val = raw, None
            if name == "":
                err_exit("Found argument '--' which wasn't expected, or isn't valid in this context")
            if name == "help":
                help_requested=True; mark('help'); i+=1; continue
            elif name == "login":
                mark('login')
                if seen_counts.get('login',0)>=1 and deferred_dup is None: deferred_dup=('login',"--login")
                seen_once('login',"--login"); login=True; i+=1; continue
            elif name == "norc":
                mark('norc')
                if seen_counts.get('norc',0)>=1 and deferred_dup is None: deferred_dup=('norc',"--norc")
                seen_once('norc',"--norc"); norc=True; i+=1; continue
            elif name == "version":
                mark('version')
                if seen_counts.get('version',0)>=1 and deferred_dup is None: deferred_dup=('version',"--version")
                seen_once('version',"--version"); version=True; i+=1; continue
            else:
                sug = did_you_mean(name, ["help","login","norc","version"])
                extra=None
                if sug: extra=sug
                err_exit(f"Found argument '--{name}' which wasn't expected, or isn't valid in this context", extra_id=extra, suggestion=sug)
        elif arg.startswith("-") and arg != "-":
            # short cluster
            cluster = arg[1:]
            j=0
            consumed_next=False
            while j < len(cluster):
                ch = cluster[j]
                if ch == 'h':
                    help_requested=True; mark('help'); j+=1; continue
                elif ch == 'l':
                    mark('login')
                    if seen_counts.get('login',0)>=1 and deferred_dup is None: deferred_dup=('login',"--login")
                    seen_once('login',"--login"); login=True; j+=1; continue
                elif ch == 'c':
                    mark('c')
                    if seen_counts.get('c',0)>=1 and deferred_dup is None: deferred_dup=('c',"-c <command>")
                    seen_once('c',"-c <command>")
                    # value is rest of cluster (with optional leading '=') or next arg if next isn't a flag-like known?
                    rest = cluster[j+1:]
                    if rest.startswith("="):
                        command = rest[1:]; j=len(cluster); continue
                    elif rest:
                        command = rest; j=len(cluster); continue
                    else:
                        # need next argv as value, but clap will not consume a flag as value.
                        # Peek: if next token looks like a known flag / help etc, then missing value (deferred)
                        # But simplest observed: -c -h -> help wins; -c --version -> missing value error mentioning --version used
                        # We implement lookahead processing by marking c pending.
                        # If no next arg: missing.
                        if i+1 >= len(argv):
                            # missing value error (help check earlier would have already flag)
                            if help_requested:
                                _write_fd(1, MAIN_HELP_TEMPLATE.format(prog=prog)); raise SystemExit(0)
                            err_exit("The argument '-c <command>' requires a value but none was supplied")
                        nxt = argv[i+1]
                        # Determine if nxt is a flag token clap would parse as flag instead of value:
                        # recognised flags: -h/--help, -l/--login, --norc, --version, -c (and clusters starting with those?)
                        def is_flag_token(t):
                            if t.startswith("--"):
                                nm=t.lstrip("-").split("=",1)[0]
                                return nm in ("help","login","norc","version")
                            if t.startswith("-") and t!="-":
                                # first char of cluster
                                return t[1] in ("h","l","c")
                            return False
                        if is_flag_token(nxt):
                            # Missing value, but clap parses the following flag(s) for usage / help priority.
                            # Handle special: if any later token is help, help wins.
                            # Scan remaining argv for help token in a simplified way.
                            # First handle --version usage inclusion example: -c --version
                            # We simulate by processing next token(s) as flags (only up to help/version)
                            # For our purposes, check if nxt (or subsequent) requests help:
                            rest_args = argv[i+1:]
                            # simple help scan: tokens that are -h/--help or cluster containing h before any unknown
                            for t in rest_args:
                                if t=="--": break
                                if t.startswith("--") and t.lstrip("-").split("=",1)[0]=="help":
                                    _write_fd(1, MAIN_HELP_TEMPLATE.format(prog=prog)); raise SystemExit(0)
                                if t.startswith("-") and not t.startswith("--") and 'h' in t[1:]:
                                    _write_fd(1, MAIN_HELP_TEMPLATE.format(prog=prog)); raise SystemExit(0)
                                # mark version/login/norc for usage if present as next token(s)
                                if t.startswith("--"):
                                    nm=t.lstrip("-").split("=",1)[0]
                                    if nm in ("login","norc","version"): mark(nm)
                                elif t.startswith("-") and t!="-":
                                    for cch in t[1:]:
                                        if cch=='l': mark('login')
                                        elif cch=='c': mark('c')
                                else:
                                    break
                            if help_requested:
                                _write_fd(1, MAIN_HELP_TEMPLATE.format(prog=prog)); raise SystemExit(0)
                            err_exit("The argument '-c <command>' requires a value but none was supplied")
                        else:
                            command = nxt; consumed_next=True; j=len(cluster); continue
                else:
                    # unknown short char; clap reports '-x' (only that char)
                    # But if help seen earlier in this cluster / before, clap unknown still? -hv gave help.
                    if help_requested:
                        _write_fd(1, MAIN_HELP_TEMPLATE.format(prog=prog)); raise SystemExit(0)
                    err_exit(f"Found argument '-{ch}' which wasn't expected, or isn't valid in this context")
            i += 2 if consumed_next else 1
            continue
        else:
            # positional FILE (including "-")
            if file is not None:
                err_exit(f"Found argument '{arg}' which wasn't expected, or isn't valid in this context")
            file = arg; i+=1; continue
    if help_requested:
        _write_fd(1, MAIN_HELP_TEMPLATE.format(prog=prog))
        raise SystemExit(0)
    if deferred_dup is not None:
        id_,disp = deferred_dup
        # usage for dup: smart usage includes that arg and other used
        err_exit(f"The argument '{disp}' was provided more than once, but cannot be used multiple times")
    # -c missing already handled when encountered at end; but if command marker seen with no command due flag-value case handled.
    return {"login":login,"norc":norc,"version":version,"command":command,"file":file}

# ----- Builtin clap handling -----
# Each builtin spec: name, prefix, help_text (without prefix, exactly as clap prints after prefix), usage_line, flags, options, positionals
# help_text examples include trailing blank line handling - we reproduce at call site.
class BuiltinClapError(Exception):
    def __init__(self, status=1):
        self.status=status

def builtin_clap_parse(spec, args, ctx):
    """Parse args (excluding builtin name). On error/help/version, print as reference and raise BuiltinClapError.
    Returns dict with 'flags' set, 'options' dict, 'positionals' list."""
    name = spec['name']; prefix = spec['prefix']; usage = spec['usage']  # e.g. "fg [job_id]"
    flags_def = spec.get('flags',[])  # list of (short,long,id)
    opts_def = spec.get('options',[]) # list of (short,long,id,valuename)
    pos_def = spec.get('positionals',[]) # list of (id,display,required,validator)
    help_text = spec['help']  # full clap help text starting "fg 0.4.2\n..."
    version_text = f"{name} 0.4.2"
    # map
    flag_by_short={}; flag_by_long={}
    for short,long,id_ in flags_def:
        if short: flag_by_short[short]=id_
        if long: flag_by_long[long]=id_
    opt_by_short={}; opt_by_long={}
    for short,long,id_,vn in opts_def:
        if short: opt_by_short[short]=(id_,vn)
        if long: opt_by_long[long]=(id_,vn)
    def fail(message, usage_override=None, is_help=False, is_version=False):
        if is_version:
            # stdout: version without newline; stderr: prefix + " \n\n"  (as observed)
            # BUT if stdout has been redirected for this builtin, our caller has already dup'd fds, so fd1 is correct.
            try: _write_fd(1, version_text)
            except Exception: pass
            _write_fd(2, f"{prefix} \n\n")
            raise BuiltinClapError(1)
        if is_help:
            _write_fd(2, f"{prefix}{help_text}\n")
            raise BuiltinClapError(1)
        # error message already formatted as clap (starting "error: ..." or help text)
        _write_fd(2, f"{prefix}{message}\n")
        raise BuiltinClapError(1)
    def error_found(argdisplay, usage_override=None, suggestion=None, used_ids=None):
        usg = usage_override or usage
        msg = f"error: Found argument '{argdisplay}' which wasn't expected, or isn't valid in this context"
        if suggestion:
            msg += _clap_suggestion_text(suggestion)
            # smart usage for builtins when suggestion? They generally show generic usage. In set duplicate cases specific.
        msg += f"\n\nUSAGE:\n    {usg}\n\nFor more information try --help\n"
        fail(msg)
    flags=set(); options={}; positionals=[]
    seen=set()
    deferred_dup=None
    used_for_usage=[]  # to build smart usage for missing-required / duplicate
    i=0; after_dd=False
    # For smart usage in some errors (read -p missing var => "read <VAR> -p <prompt>"; set -e dup => "set -e")
    def smart_usage_for_missing():
        # Only implement cases we know: if spec has custom function
        fn = spec.get('smart_usage')
        if fn:
            return fn(flags, options, positionals, seen)
        return usage
    while i < len(args):
        arg=args[i]
        if after_dd:
            # positional
            if len(positionals) >= len(pos_def):
                error_found(arg)
            # validate later
            positionals.append(arg); i+=1; continue
        if arg=="--":
            after_dd=True; i+=1; continue
        if arg.startswith("--") and arg!="--":
            raw=arg.lstrip("-")
            if "=" in raw: nm,val=raw.split("=",1)
            else: nm,val=raw,None
            if nm=="help":
                fail(None,is_help=True)
            if nm=="version":
                # structopt auto version long is --version for builtins (and -V)
                fail(None,is_version=True)
            if nm in flag_by_long:
                fid=flag_by_long[nm]
                if fid in seen and deferred_dup is None:
                    deferred_dup=(fid, f"--{nm}" if spec['name']=='set' else nm)
                seen.add(fid); flags.add(fid); i+=1; continue
            if nm in opt_by_long:
                oid,vn=opt_by_long[nm]
                if val is not None:
                    options[oid]=val; seen.add(oid); i+=1; continue
                else:
                    # needs next
                    if i+1>=len(args):
                        # clap behaviour observed for read -p: reports missing required positional instead in some cases
                        # generic missing value:
                        # If there's a required positional missing, reference may report that (see read spec handling below)
                        # We'll produce missing value error unless spec overrides
                        # For read: fall through to missing-required check by marking option present without value
                        if name=="read" and oid=="prompt":
                            seen.add(oid); options[oid]=None; i+=1; continue
                        msg=f"error: The argument '--{nm} <{vn}>' requires a value but none was supplied\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n"
                        fail(msg)
                    nxt=args[i+1]
                    # If next is a flag-like, clap treats as missing? For simplicity consume anyway unless it's help/version
                    options[oid]=nxt; seen.add(oid); i+=2; continue
            # unknown long
            cand=[]
            for s,l,id_ in flags_def:
                if l: cand.append(l)
            for s,l,id_,vn in opts_def:
                if l: cand.append(l)
            cand+=["help","version"]
