# ----- Builtin clap handling -----
# Each builtin spec: name, prefix, help_text (without prefix, exactly as clap prints after prefix), usage_line, flags, options, positionals
# help_text examples include trailing blank line handling - we reproduce at call site.
class BuiltinClapError(Exception):
    def __init__(self, status=1):
        self.status=status

def builtin_clap_parse(spec, args, ctx):
    """Parse args (excluding builtin name). On error/help/version, print as reference and raise BuiltinClapError.
    Returns dict with 'flags' set, 'options' dict, 'positionals' list."""
    name = spec['name']; prefix = spec['prefix']; usage = spec['usage']  # e.g. "fg [job_id]"
    flags_def = spec.get('flags',[])  # list of (short,long,id)
    opts_def = spec.get('options',[]) # list of (short,long,id,valuename)
    pos_def = spec.get('positionals',[]) # list of (id,display,required,validator)
    help_text = spec['help']  # full clap help text starting "fg 0.4.2\n..."
    version_text = f"{name} 0.4.2"
    # map
    flag_by_short={}; flag_by_long={}
    for short,long,id_ in flags_def:
        if short: flag_by_short[short]=id_
        if long: flag_by_long[long]=id_
    opt_by_short={}; opt_by_long={}
    for short,long,id_,vn in opts_def:
        if short: opt_by_short[short]=(id_,vn)
        if long: opt_by_long[long]=(id_,vn)
    def fail(message, usage_override=None, is_help=False, is_version=False):
        if is_version:
            # stdout: version without newline; stderr: prefix + " \n\n"  (as observed)
            # BUT if stdout has been redirected for this builtin, our caller has already dup'd fds, so fd1 is correct.
            try: _write_fd(1, version_text)
            except Exception: pass
            _write_fd(2, f"{prefix} \n\n")
            raise BuiltinClapError(1)
        if is_help:
            _write_fd(2, f"{prefix}{help_text}\n")
            raise BuiltinClapError(1)
        # error message already formatted as clap (starting "error: ..." or help text)
        _write_fd(2, f"{prefix}{message}\n")
        raise BuiltinClapError(1)
    def error_found(argdisplay, usage_override=None, suggestion=None, used_ids=None):
        usg = usage_override or usage
        msg = f"error: Found argument '{argdisplay}' which wasn't expected, or isn't valid in this context"
        if suggestion:
            msg += _clap_suggestion_text(suggestion)
            # smart usage for builtins when suggestion? They generally show generic usage. In set duplicate cases specific.
        msg += f"\n\nUSAGE:\n    {usg}\n\nFor more information try --help\n"
        fail(msg)
