    seen=set()
    deferred_dup=None
    used_for_usage=[]  # to build smart usage for missing-required / duplicate
    i=0; after_dd=False
    # For smart usage in some errors (read -p missing var => "read <VAR> -p <prompt>"; set -e dup => "set -e")
    def smart_usage_for_missing():
        # Only implement cases we know: if spec has custom function
        fn = spec.get('smart_usage')
        if fn:
            return fn(flags, options, positionals, seen)
        return usage
    while i < len(args):
        arg=args[i]
        if after_dd:
            # positional
            if len(positionals) >= len(pos_def):
                error_found(arg)
            # validate later
            positionals.append(arg); i+=1; continue
        if arg=="--":
            after_dd=True; i+=1; continue
        if arg.startswith("--") and arg!="--":
            raw=arg.lstrip("-")
            if "=" in raw: nm,val=raw.split("=",1)
            else: nm,val=raw,None
            if nm=="help":
                fail(None,is_help=True)
            if nm=="version":
                # structopt auto version long is --version for builtins (and -V)
                fail(None,is_version=True)
            if nm in flag_by_long:
                fid=flag_by_long[nm]
                if fid in seen and deferred_dup is None:
                    deferred_dup=(fid, f"--{nm}" if spec['name']=='set' else nm)
                seen.add(fid); flags.add(fid); i+=1; continue
            if nm in opt_by_long:
                oid,vn=opt_by_long[nm]
                if val is not None:
                    options[oid]=val; seen.add(oid); i+=1; continue
                else:
                    # needs next
                    if i+1>=len(args):
                        # clap behaviour observed for read -p: reports missing required positional instead in some cases
                        # generic missing value:
                        # If there's a required positional missing, reference may report that (see read spec handling below)
                        # We'll produce missing value error unless spec overrides
                        # For read: fall through to missing-required check by marking option present without value
                        if name=="read" and oid=="prompt":
                            seen.add(oid); options[oid]=None; i+=1; continue
                        msg=f"error: The argument '--{nm} <{vn}>' requires a value but none was supplied\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n"
                        fail(msg)
                    nxt=args[i+1]
                    # If next is a flag-like, clap treats as missing? For simplicity consume anyway unless it's help/version
                    options[oid]=nxt; seen.add(oid); i+=2; continue
            # unknown long
            cand=[]
            for s,l,id_ in flags_def:
                if l: cand.append(l)
            for s,l,id_,vn in opts_def:
                if l: cand.append(l)
            cand+=["help","version"]
            sug=did_you_mean(nm,cand)
            error_found(f"--{nm}",suggestion=sug)
        elif arg.startswith("-") and arg!="-" and arg!="":
            cluster=arg[1:]
            j=0; consumed_next=False
            while j<len(cluster):
                ch=cluster[j]
                if ch=='h':
                    fail(None,is_help=True)
                if ch=='V':
                    fail(None,is_version=True)
                if ch in flag_by_short:
                    fid=flag_by_short[ch]
                    if fid in seen and deferred_dup is None:
                        deferred_dup=(fid, f"-{ch}")
                    seen.add(fid); flags.add(fid); j+=1; continue
                if ch in opt_by_short:
                    oid,vn=opt_by_short[ch]
                    rest=cluster[j+1:]
                    if rest.startswith("="):
                        options[oid]=rest[1:]; seen.add(oid); j=len(cluster); continue
                    elif rest:
                        options[oid]=rest; seen.add(oid); j=len(cluster); continue
                    else:
                        if i+1>=len(args):
                            if name=="read" and oid=="prompt":
                                seen.add(oid); options[oid]=None; j=len(cluster); continue
                            msg=f"error: The argument '-{ch} <{vn}>' requires a value but none was supplied\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n"
                            fail(msg)
                        options[oid]=args[i+1]; seen.add(oid); consumed_next=True; j=len(cluster); continue
                # unknown short - clap reports '-x' full? For '-1' it reports '-1', for '-x' '-x', for '-xyz' likely '-x'
                # If the arg looks like a negative number / single char cluster unknown, it shows whole arg in some cases?
                # Observations: wait -1 => '-1', fg -x => '-x', set - (single dash) handled elsewhere.
                # We'll report f"-{ch}" if cluster length>1 and ch is alpha, else whole arg.
                disp = arg if len(cluster)==1 else f"-{ch}"
                # Special: arguments like '-1' and '-p' when no such flag: clap shows '-1' (that's f"-{ch}")
                error_found(disp)
            i+= 2 if consumed_next else 1
            continue
        else:
            # positional (including "-")
            if len(positionals) >= len(pos_def):
                error_found(arg)
            positionals.append(arg); i+=1; continue
    if deferred_dup is not None:
        fid,disp = deferred_dup
        # smart usage: for set, "set -e"
        usg = usage
        if name=="set":
            usg = f"set {disp}"
        msg=f"error: The argument '{disp}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {usg}\n\nFor more information try --help\n"
        fail(msg)
    # missing required positionals
    missing=[]
    for idx,(pid,disp,req,validator) in enumerate(pos_def):
        if req and idx>=len(positionals):
            missing.append(disp)
    if missing:
        usg=smart_usage_for_missing()
        msg="error: The following required arguments were not provided:\n"
        for m in missing: msg+=f"    {m}\n"
        msg+=f"\nUSAGE:\n    {usg}\n\nFor more information try --help\n"
        fail(msg)
    # validators for positionals (e.g. shift n numeric)
    for idx,(pid,disp,req,validator) in enumerate(pos_def):
        if idx < len(positionals) and validator:
            ok, errmsg = validator(positionals[idx])
            if not ok:
                msg=f"error: Invalid value for '{disp}': {errmsg}\n"
                fail(msg)
    return {"flags":flags,"options":options,"positionals":positionals}

def _validator_usize(s):
    # Rust usize parse: optional leading '+', digits only, fits u64
    t=s
    if t.startswith("+"): t=t[1:]
    if t=="" or not t.isdigit():
        return (False,"invalid digit found in string")
    try:
        v=int(t)
    except:
        return (False,"invalid digit found in string")
    if v>18446744073709551615:
        return (False,"number too large to fit in target type")
    return (True,"")

