class Parser:
    def __init__(self, src):
        self.src=src; self.n=len(src); self.pos=0
        self.conversion_panics=[]  # list of (pos, ShellPanic)
        self.pending_heredocs=[]
        self.heredoc_panic_no_newline=False
    # ----- utilities -----
    def eof(self): return self.pos>=self.n
    def peek(self): return self.src[self.pos] if self.pos<self.n else ""
    def peek2(self): return self.src[self.pos:self.pos+2]
    def startswith(self,s): return self.src.startswith(s,self.pos)
    def error(self,pos,expected):
        raise ParseError(self.src,pos,expected)
    def record_panic(self,pos,loc,msg,frames=18):
        self.conversion_panics.append((pos,ShellPanic(loc,msg,frames)))
    def skip_spaces_tabs(self):
        while self.pos<self.n and self.src[self.pos] in " \t\r":
            self.pos+=1
    def skip_spaces_tabs_comments(self):
        while True:
            self.skip_spaces_tabs()
            if self.peek()=='#':
                # comment to (not including) newline
                while self.pos<self.n and self.src[self.pos] != "\n":
                    self.pos+=1
                continue
            break
