        if after>=self.n: return True
        ch=self.src[after]
        return ch in " \t\r\n;|&(){}" or ch=='#'  # # comment after space handled elsewhere; plain kw# is word?
    def peek_keyword(self):
        # return raw standalone word at pos if it is a bare literal token, else None
        i=self.pos
        if i>=self.n: return None
        if self.src[i] in "'\"\\$`": return None
        j=i
        while j<self.n and self.src[j] not in " \t\r\n;|&<>(){}":
