                self.error(self.pos, EXPECTED_CMD_START if not items else EXPECTED_AFTER_WORD)
            if ch in ")}":
                if ch in stop_chars: break
                self.error(self.pos, EXPECTED_CMD_START)
            if ch=='&' and not self.startswith("&&"):
