    def parse_pipeline(self, stop_keywords, stop_chars, stop_case=False):
        start=self.pos
        stages=[self.parse_command(stop_keywords, stop_chars, stop_case)]
        while True:
            save=self.pos
            self.skip_spaces_tabs_comments()
            if self.peek()=='|' and not self.startswith("||"):
                self.pos+=1
                self._suppress_heredoc=getattr(self,'_suppress_heredoc',0)+1
