        return self.value

class Frame:
    __slots__=("locals","params")
    def __init__(self,params): self.locals={}; self.params=list(params)

class Job:
    __slots__=("id","pgid","pids","description","status","state","procs")
    def __init__(self,id_,pgid,pids,description):
