def simple_items(node):
    words=[]; redirects=[]
    for it in node.items:
        if isinstance(it, Word): words.append(it)
        elif isinstance(it, Redirect): redirects.append(it)
    return words,redirects

def expand_simple_argv(shell, node):
    words,redirects=simple_items(node)
    if not words:
        return [], redirects, False
    # Alias check on first word
    argv=[]
    alias_applied=False
    first_name=literal_word_name(words[0])
    if first_name is not None and first_name in shell.aliases:
        body=shell.aliases[first_name]
        toks=body.split()
        argv.extend(toks)
        alias_applied=True
        rest_words=words[1:]
    else:
        rest_words=words
    for w in rest_words:
        argv.extend(expand_word_to_fields(shell,w,allow_glob=True))
    if alias_applied and not argv:
        argv=[""]
    return argv, redirects, alias_applied

def run_pipeline(shell, pipeline, background=False, andor_description=""):
    try:
        if all(stage_is_process_capable(shell,st) for st in pipeline.stages):
            return run_pipeline_concurrent(shell,pipeline,background,andor_description)
        else:
            return run_pipeline_sequential(shell,pipeline,background,andor_description)
    finally:
        # Close process substitution fds created during this pipeline, unless this is an async interactive job whose children may still need them.
        # In async case concurrent launcher clears shell.proc_subst_fds ownership to job; for now close only if not background interactive.
        if not (background and shell.interactive):
            close_proc_subst_fds(shell)

def stage_is_process_capable(shell, stage):
    if isinstance(stage, Subshell):
        return True
    if isinstance(stage, SimpleCommand):
        words,_=simple_items(stage)
        if not words: return False
        name=literal_word_name(words[0])
        if name is None: return False
        if name in shell.aliases:
            toks=shell.aliases[name].split()
            if not toks: return False
            name=toks[0]
        if name in shell.functions: return False
        if name in BUILTINS: return False
        return True
    return False

def run_pipeline_sequential(shell, pipeline, background=False, andor_description=""):
    input_fd=None  # temp file fd for next stage stdin
    status=0
    launched_external=False
    shell._stage_launched_external=False
    for idx,stage in enumerate(pipeline.stages):
        is_last=(idx==len(pipeline.stages)-1)
        saved={}
        out_tf=None
        try:
            if input_fd is not None:
                saved[0]=dup_above(0,10) if _fd_open(0) else None
                os.lseek(input_fd,0,0); os.dup2(input_fd,0)
            if not is_last:
                saved[1]=dup_above(1,10) if _fd_open(1) else None
                out_tf=tempfile.TemporaryFile()
                os.dup2(out_tf.fileno(),1)
            status=run_command_dispatch(shell, stage)
            shell.last_status=status
        finally:
            # restore 1 then 0
            if 1 in saved:
                if saved[1] is not None: os.dup2(saved[1],1); os.close(saved[1])
                else:
                    try: os.close(1)
                    except Exception: pass
            if 0 in saved:
                if saved[0] is not None: os.dup2(saved[0],0); os.close(saved[0])
                else:
                    try: os.close(0)
                    except Exception: pass
            if input_fd is not None:
                try: os.close(input_fd)
                except Exception: pass
                input_fd=None
            if out_tf is not None:
                out_tf.flush()
                input_fd=out_tf.fileno()
                # detach so closing python object later doesn't close? Keep object in shell temp list
                if not hasattr(shell,'_temp_files'): shell._temp_files=[]
                shell._temp_files.append(out_tf)
        if shell._stage_launched_external:
            launched_external=True; shell._stage_launched_external=False
    if input_fd is not None:
        try: os.close(input_fd)
        except Exception: pass
    if background and launched_external:
        # Non-interactive synchronous background: report Done (job id is lowest free, usually 1)
        if not shell.interactive:
            jid=allocate_job_id(shell)
            desc=andor_description
            shell_write_out(f"[{jid}] Done: {desc}\n")
        else:
            # In interactive, sequential stages already finished; report too? Reference for builtin/external mixed may not create a job.
            pass
    return status

def _fd_open(fd):
    try:
        os.fstat(fd); return True
    except Exception:
        return False

def allocate_job_id(shell):
    i=1
    while i in shell.jobs: i+=1
    return i

def run_pipeline_concurrent(shell, pipeline, background=False, andor_description=""):
    # Prepare stages
    prepared_stages=[]
    try:
        for stage in pipeline.stages:
            if isinstance(stage, Subshell):
                prepared_stages.append(('subshell',stage,None,None,[],None))
                continue
            # Simple external
            argv,redirects,alias_applied=expand_simple_argv(shell, stage)
            if not argv:
                prepared_stages.append(('notfound',stage,[""],None,[],[])); continue
            # Function/builtin shouldn't happen (literal classification), but fallback marker
            if argv[0] in shell.functions or argv[0] in BUILTINS:
                # Abort concurrent preparation and use sequential (expansions already happened for this stage - would double-expand in sequential!)
                # To avoid complexity, treat as notfound? This case is prevented by classifier for literal names.
                prepared_stages.append(('notfound',stage,argv,None,[],[])); continue
            prefix=expand_assignments(shell, stage.assignments)
            prep=prepare_redirects(shell, redirects)
            kind,path=resolve_command(shell, argv[0])
            if kind=='notfound':
                shell_error(f"nsh: command not found `{argv[0]}'")
                close_prepared(prep)
                prepared_stages.append(('notfound',stage,argv,None,[],[]))
            else:
                env=build_env_list(shell, prefix)
                prepared_stages.append(('external',stage,argv,path,prep,env))
    except (NoMatchesError, ExpansionError):
        for ent in prepared_stages:
            if ent[4]: close_prepared(ent[4])
        return 1
    n=len(prepared_stages)
    pipes=[]
    for i in range(n-1):
        pipes.append(os.pipe())
    pids=[]
    pgid=None
    is_job = any(ent[0]=='external' for ent in prepared_stages)
    job_control = shell.interactive and _fd_open(0) and os.isatty(0)
    for idx,ent in enumerate(prepared_stages):
        kind,stage,argv,path,prep,env = ent
        stdin_fd = pipes[idx-1][0] if idx>0 else None
        stdout_fd = pipes[idx][1] if idx<n-1 else None
        pid=os.fork()
        if pid==0:
            try:
                reset_child_signals()
                if job_control or (background and shell.interactive):
                    try:
                        os.setpgid(0, pgid if pgid else 0)
                    except Exception: pass
                if stdin_fd is not None: os.dup2(stdin_fd,0)
                if stdout_fd is not None: os.dup2(stdout_fd,1)
                for r,w in pipes:
                    for fd in (r,w):
                        try: os.close(fd)
                        except Exception: pass
                if kind=='subshell':
                    shell.heredoc_supported=False
                    # apply no redirects (subshell stage has none syntactically)
                    def go(st=stage):
                        return run_compound_list(shell, st.body)
                    run_in_subshell_child(shell, go)
                elif kind=='notfound':
                    os._exit(1)
                else:
                    apply_prepared_redirects(prep)
                    try:
                        os.execve(os.fsencode(path), [os.fsencode(a) for a in argv], encode_env(env))
                    except OSError as e:
                        try: _write_fd(2, failed_exec_message(argv[0],e)+"\n")
                        except Exception: pass
                        os._exit(1)
            except BaseException:
                os._exit(1)
        # parent
        pids.append(pid)
        if pgid is None: pgid=pid
        if job_control or (background and shell.interactive):
            try: os.setpgid(pid, pgid)
            except Exception: pass
        if ent[0]=='external':
            shell._stage_launched_external=True
    for r,w in pipes:
        try: os.close(r)
        except Exception: pass
        try: os.close(w)
        except Exception: pass
    for ent in prepared_stages:
        if ent[4]: close_prepared(ent[4])
    if n>0:
        shell.last_bg_pid = pids[0] if background else shell.last_bg_pid
        if background:
            shell.last_bg_pid=pids[0]
    if background and shell.interactive:
        # Create async job if there is a real external process; subshell-only pipelines are waited below like reference? (they returned prompt? unknown)
        if is_job:
            jid=allocate_job_id(shell)
            job=Job(jid, pgid, pids[:], andor_description)
            shell.jobs[jid]=job
            return 0
        # else fall through to wait
    # Foreground / noninteractive background: wait all
    statuses={}
    stopped=False
    if job_control and not background:
        # give terminal to job pgid
        try:
            os.tcsetpgrp(0, pgid)
        except OSError as e:
            # reference panics in interactive when not a controlling terminal
            # Kill/wait children? Panic will terminate shell; children may.
            panic("src/process.rs:186:24", f"failed to tcsetpgrp: {errno_name(e.errno or 0)}", frames=21)
    remaining=set(pids)
    while remaining:
        try:
            wpid,st=os.waitpid(-pgid if (job_control or (background and shell.interactive)) and pgid else -1, os.WUNTRACED)
        except ChildProcessError:
            break
        except InterruptedError:
            continue
        if wpid in remaining:
            if os.WIFSTOPPED(st):
                stopped=True; statuses[wpid]=-1
                # job stopped: keep remaining? A stopped job means all processes in pg may stop eventually; break to return to prompt in interactive
                # For non-jobcontrol, a self-stopping child: treat as done for that pid.
                remaining.discard(wpid)
                if job_control:
                    # create a stopped job for the whole pipeline
                    jid=allocate_job_id(shell)
                    job=Job(jid,pgid,pids[:],andor_description); job.state="stopped"; shell.jobs[jid]=job
                    # status will be -1 for last
                    break
            else:
                statuses[wpid]=wait_status_to_code(st); remaining.discard(wpid)
        # else ignore (proc subst children etc reaped here could be consumed - acceptable)
    if job_control and not background:
        try: os.tcsetpgrp(0, shell.shell_pgid)
        except Exception: pass
    status=statuses.get(pids[-1], -1 if stopped else 0) if pids else 0
    if background and not shell.interactive and is_job:
        jid=allocate_job_id(shell)
        shell_write_out(f"[{jid}] Done: {andor_description}\n")
    return status

def run_command_dispatch(shell, node):
    # Compound depth for heredoc support: entering compounds handled in their runners
    if isinstance(node, SimpleCommand):
        return run_simple_command(shell,node)
    if isinstance(node, Subshell):
        return run_subshell(shell,node)
    if isinstance(node, BraceGroup):
        return with_heredoc_unsupported(shell, lambda: run_compound_list(shell,node.body))
    if isinstance(node, If):
        return with_heredoc_unsupported(shell, lambda: run_if(shell,node))
    if isinstance(node, While):
        return with_heredoc_unsupported(shell, lambda: run_while(shell,node))
    if isinstance(node, ForWords):
        return with_heredoc_unsupported(shell, lambda: run_for_words(shell,node))
    if isinstance(node, ForArith):
        return with_heredoc_unsupported(shell, lambda: run_for_arith(shell,node))
    if isinstance(node, Case):
        return with_heredoc_unsupported(shell, lambda: run_case(shell,node))
    if isinstance(node, FunctionDef):
        shell.functions[node.name]=node.body; shell.last_status=0; return 0
    if isinstance(node, Conditional):
        st=eval_conditional(shell,node.expr); shell.last_status=st; return st
    if isinstance(node, LocalCommand):
        return run_local(shell,node)
    if isinstance(node, ReturnCommand):
        shell.last_status=0; raise ReturnSignal()
    if isinstance(node, BreakCommand):
        shell.last_status=0; raise BreakSignal()
    if isinstance(node, ContinueCommand):
        shell.last_status=0; raise ContinueSignal()
    return 0

def with_heredoc_unsupported(shell, fn):
    old=shell.heredoc_supported; shell.heredoc_supported=False
    try:
        return fn()
    finally:
        shell.heredoc_supported=old

def run_subshell(shell, node):
    pid=os.fork()
    if pid==0:
        shell.heredoc_supported=False
        def go():
            return run_compound_list(shell,node.body)
        run_in_subshell_child(shell,go)
    # parent wait
    code,stopinfo=wait_for_pid(pid)
    shell.last_status=code
    return code

def run_if(shell,node):
    cond_status=run_compound_list(shell,node.cond)
    if cond_status==0:
        st=run_compound_list(shell,node.then) if node.then.items else 0
        shell.last_status=st; return st
    for ec,eb in node.elifs:
        if run_compound_list(shell,ec)==0:
            st=run_compound_list(shell,node.then) if node.then.items else 0
            shell.last_status=st; return st
    if node.otherwise is not None:
        st=run_compound_list(shell,node.otherwise) if node.otherwise.items else 0
        shell.last_status=st; return st
    shell.last_status=0; return 0

def run_while(shell,node):
    last_status=0; last_signal=None; iterations=0
    while True:
        cond_status=run_compound_list(shell,node.cond)
        if cond_status!=0: break
        iterations+=1
        try:
            last_status=run_compound_list(shell,node.body); last_signal=None
        except (BreakSignal,ContinueSignal,ReturnSignal) as sig:
            last_signal=sig; last_status=shell.last_status
            continue
    if iterations==0:
        shell.last_status=0
        if last_signal: raise last_signal
        return 0
    shell.last_status=last_status
    if last_signal: raise last_signal
    return last_status

def run_for_words(shell,node):
    try:
        vals=[]
        for w in node.words:
            vals.extend(expand_word_to_fields(shell,w,allow_glob=True))
    except NoMatchesError:
        shell.last_status=1; return 1
    for v in vals:
        shell.set_var(node.var,v)
        try:
            run_compound_list(shell,node.body)
        except BreakSignal:
            break
        except ContinueSignal:
            continue
    shell.last_status=0; return 0

def run_for_arith(shell,node):
    eval_arith(shell,node.init)
    while True:
        cond=eval_arith(shell,node.cond)
        if not cond: break
        try:
            run_compound_list(shell,node.body)
        except BreakSignal:
            break
        except ContinueSignal:
            pass
        eval_arith(shell,node.step)
    shell.last_status=0; return 0

def run_case(shell,node):
    subject=expand_word_to_string(shell,node.subject)
    for patterns,body in node.clauses:
        matched=False
        for pw in patterns:
            toks=expand_word_to_pattern(shell,pw)
            if pattern_matches(toks,subject):
                matched=True; break
        if matched:
            if not body.items:
                shell.last_status=0; return 0
            st=run_compound_list(shell,body); shell.last_status=st; return st
    shell.last_status=0; return 0

def run_local(shell,node):
    if not shell.frames:
        shell_error("nsh: local variable can only be used in a function")
        shell.last_status=1; return 1
    for name,val,is_array in node.pairs:
        if val is None:
            shell.set_local(name,"",False)
        elif is_array:
            shell.set_local(name,[expand_word_to_string(shell,w) for w in val],True)
        else:
            shell.set_local(name,expand_word_to_string(shell,val),False)
    shell.last_status=0; return 0

def eval_conditional(shell, expr):
    # expr ('or',[('and',[cmp...])])
    def eval_cmp(cmp):
        items=cmp[1]
        if len(items)==1:
            # expansion side effects still happen
            expand_word_to_string(shell,items[0]); return True
        if len(items)!=3:
            panic("src/eval.rs:541:17","internal error: entered unreachable code",frames=18)
        leftw,op,rightw=items
        if op in ("=","==","!="):
            left=expand_word_to_string(shell,leftw)
            toks=expand_word_to_pattern(shell,rightw)
            res=pattern_matches(toks,left)
            return (not res) if op=="!=" else res
        else:
            left=expand_word_to_string(shell,leftw); right=expand_word_to_string(shell,rightw)
            l=parse_i32_or0(left); r=parse_i32_or0(right)
            if op=="-eq": return l==r
            if op=="-ne": return l!=r
            if op=="-lt": return l<r
            if op=="-gt": return l>r
            if op=="-le": return l<=r
            if op=="-ge": return l>=r
        return False
    def eval_and(node):
        for cmp in node[1]:
            if not eval_cmp(cmp): return False
        return True
    # or
    for andnode in expr[1]:
        if eval_and(andnode): return 0
    return 1

