def literal_word_name(word):
    # if word consists solely of literal/escaped/single/dquoted-literal spans, return its text else None
    out=""
    for sp in word.spans:
        if sp.kind in ('literal','escaped','single_quoted'):
            out+=sp.text
        elif sp.kind=='double_quoted':
            for isp in sp.inner:
                if isp.kind in ('literal','escaped','single_quoted'):
                    out+=isp.text
                else:
                    return None
        else:
            return None
    return out

def simple_items(node):
    words=[]; redirects=[]
    for it in node.items:
        if isinstance(it, Word): words.append(it)
        elif isinstance(it, Redirect): redirects.append(it)
    return words,redirects

def expand_simple_argv(shell, node):
    words,redirects=simple_items(node)
    if not words:
        return [], redirects, False
    # Alias check on first word
    argv=[]
    alias_applied=False
    first_name=literal_word_name(words[0])
    if first_name is not None and first_name in shell.aliases:
        body=shell.aliases[first_name]
        toks=body.split()
        argv.extend(toks)
        alias_applied=True
        rest_words=words[1:]
    else:
        rest_words=words
    for w in rest_words:
        argv.extend(expand_word_to_fields(shell,w,allow_glob=True))
    if alias_applied and not argv:
        argv=[""]
    return argv, redirects, alias_applied

def run_pipeline(shell, pipeline, background=False, andor_description=""):
    try:
        if all(stage_is_process_capable(shell,st) for st in pipeline.stages):
            return run_pipeline_concurrent(shell,pipeline,background,andor_description)
        else:
            return run_pipeline_sequential(shell,pipeline,background,andor_description)
    finally:
        # Close process substitution fds created during this pipeline, unless this is an async interactive job whose children may still need them.
        # In async case concurrent launcher clears shell.proc_subst_fds ownership to job; for now close only if not background interactive.
        if not (background and shell.interactive):
            close_proc_subst_fds(shell)

def stage_is_process_capable(shell, stage):
    if isinstance(stage, Subshell):
        return True
    if isinstance(stage, SimpleCommand):
        words,_=simple_items(stage)
        if not words: return False
        name=literal_word_name(words[0])
        if name is None: return False
        if name in shell.aliases:
            toks=shell.aliases[name].split()
            if not toks: return False
            name=toks[0]
        if name in shell.functions: return False
        if name in BUILTINS: return False
        return True
    return False

def run_pipeline_sequential(shell, pipeline, background=False, andor_description=""):
    input_fd=None  # temp file fd for next stage stdin
    status=0
    launched_external=False
    shell._stage_launched_external=False
    for idx,stage in enumerate(pipeline.stages):
        is_last=(idx==len(pipeline.stages)-1)
        saved={}
        out_tf=None
        try:
            if input_fd is not None:
                saved[0]=dup_above(0,10) if _fd_open(0) else None
                os.lseek(input_fd,0,0); os.dup2(input_fd,0)
            if not is_last:
                saved[1]=dup_above(1,10) if _fd_open(1) else None
                out_tf=tempfile.TemporaryFile()
                os.dup2(out_tf.fileno(),1)
            status=run_command_dispatch(shell, stage)
            shell.last_status=status
        finally:
            # restore 1 then 0
            if 1 in saved:
                if saved[1] is not None: os.dup2(saved[1],1); os.close(saved[1])
                else:
                    try: os.close(1)
                    except Exception: pass
            if 0 in saved:
                if saved[0] is not None: os.dup2(saved[0],0); os.close(saved[0])
                else:
                    try: os.close(0)
                    except Exception: pass
            if input_fd is not None:
                try: os.close(input_fd)
                except Exception: pass
                input_fd=None
            if out_tf is not None:
                out_tf.flush()
                input_fd=out_tf.fileno()
                # detach so closing python object later doesn't close? Keep object in shell temp list
                if not hasattr(shell,'_temp_files'): shell._temp_files=[]
                shell._temp_files.append(out_tf)
        if shell._stage_launched_external:
            launched_external=True; shell._stage_launched_external=False
    if input_fd is not None:
        try: os.close(input_fd)
        except Exception: pass
    if background and launched_external:
        # Non-interactive synchronous background: report Done (job id is lowest free, usually 1)
        if not shell.interactive:
            jid=allocate_job_id(shell)
            desc=andor_description
            shell_write_out(f"[{jid}] Done: {desc}\n")
        else:
            # In interactive, sequential stages already finished; report too? Reference for builtin/external mixed may not create a job.
            pass
    return status

