def literal_word_name(word):
    # if word consists solely of literal/escaped/single/dquoted-literal spans, return its text else None
    out=""
    for sp in word.spans:
        if sp.kind in ('literal','escaped','single_quoted'):
            out+=sp.text
        elif sp.kind=='double_quoted':
            for isp in sp.inner:
                if isp.kind in ('literal','escaped','single_quoted'):
                    out+=isp.text
                else:
                    return None
        else:
            return None
    return out

