def eval_conditional(shell, expr):
    # expr ('or',[('and',[cmp...])])
    def eval_cmp(cmp):
        items=cmp[1]
        if len(items)==1:
            # expansion side effects still happen
            expand_word_to_string(shell,items[0]); return True
        if len(items)!=3:
            panic("src/eval.rs:541:17","internal error: entered unreachable code",frames=18)
        leftw,op,rightw=items
        if op in ("=","==","!="):
            left=expand_word_to_string(shell,leftw)
            toks=expand_word_to_pattern(shell,rightw)
            res=pattern_matches(toks,left)
            return (not res) if op=="!=" else res
        else:
            left=expand_word_to_string(shell,leftw); right=expand_word_to_string(shell,rightw)
            l=parse_i32_or0(left); r=parse_i32_or0(right)
            if op=="-eq": return l==r
            if op=="-ne": return l!=r
            if op=="-lt": return l<r
            if op=="-gt": return l>r
            if op=="-le": return l<=r
            if op=="-ge": return l>=r
        return False
    def eval_and(node):
        for cmp in node[1]:
            if not eval_cmp(cmp): return False
        return True
    # or
    for andnode in expr[1]:
        if eval_and(andnode): return 0
    return 1

