def run_builtin(shell, name, argv, redirects, node):
    # Special handling for exec/exit/eval/source concerning redirects
    # Returns status int. May raise ShellExit for exit/exec success (exec never returns on success), Return etc via eval/source.
    args=argv[1:]
    if name=="exec":
        return builtin_exec(shell,args,redirects,node)
    if name=="exit":
        # Prepare/open redirects (files created), apply them (doesn't matter) then exit with 0 if any redirect, else parsed.
        try:
            prep=prepare_redirects(shell,redirects)
            close_prepared(prep)
        except ExpansionError:
            return 1
        if len(args)==0:
            code=0
        elif len(args)==1:
            a=args[0]
            if re.fullmatch(r'[+-]?[0-9]+',a or ""):
                try:
                    v=int(a)
                    if v>2147483647 or v<-2147483648: code=1
                    else: code=v
                except: code=1
            else: code=1
        else:
            code=1
        raise ShellExit(0 if redirects else code)
