        try:
            prep=prepare_redirects(shell,redirects); close_prepared(prep)
        except ExpansionError:
            return 1
        if name=="eval": return builtin_eval(shell,args)
        else: return builtin_source(shell,args)
    # General builtin with redirects applied in parent
    try:
        prep, saved = apply_redirects_in_parent(shell, redirects)
    except ExpansionError:
        return 1
    try:
        return dispatch_builtin(shell,name,args,argv)
    finally:
