def builtin_echo(shell,args):
    newline=True; escapes=False; rest=args
    if args:
        a0=args[0]
        if a0=="-n": newline=False; rest=args[1:]
        elif a0=="-e": escapes=True; rest=args[1:]
        elif a0 in ("-ne","-en"): newline=False; escapes=True; rest=args[1:]
    def process(s):
        if not escapes: return s
        out=""; i=0
        while i<len(s):
            if s[i]=='\\' and i+1<len(s):
                n=s[i+1]
                if n=='n': out+="\n"; i+=2; continue
                if n=='t': out+="\t"; i+=2; continue
                if n=='e': out+="\x1b"; i+=2; continue
                out+=s[i:i+2]; i+=2; continue
            out+=s[i]; i+=1
        return out
    text=" ".join(process(a) for a in rest)
    if newline: text+="\n"
    shell_write_out(text)
    return 0

