def parse_job_id_arg(shell,arg):
    # returns int job id or raises ValueError with message printed
    if not arg.startswith("%"):
        shell_error(f"nsh: invalid job id `{arg}'"); raise ExpansionError()
    rest=arg[1:]
    # Rust parse usize: optional + then digits
    t=rest[1:] if rest.startswith("+") else rest
    if not t.isdigit() or t=="":
        shell_error(f"nsh: invalid job id `{rest}'"); raise ExpansionError()
    try:
        v=int(t)
        if v>18446744073709551615: raise OverflowError()
    except OverflowError:
        shell_error(f"nsh: invalid job id `{rest}'"); raise ExpansionError()
    if v not in shell.jobs:
        shell_error(f"nsh: no such job `{v}'"); raise ExpansionError()
    return v

def check_jobs(shell, report=True):
    # Reap proc-subst children opportunistically (ignore)
    # Poll async jobs
    done_ids=[]
    for jid,job in list(shell.jobs.items()):
        all_done=True; any_stopped=False
        for pid in list(job.pids):
            try:
                wpid,st=os.waitpid(pid, os.WNOHANG|os.WUNTRACED)
            except ChildProcessError:
                continue
            if wpid==0:
                all_done=False; continue
            if os.WIFSTOPPED(st):
                any_stopped=True; all_done=False
            else:
                job.status=wait_status_to_code(st)
        if any_stopped:
            job.state="stopped"
        elif all_done:
            job.state="done"; done_ids.append(jid)
    for jid in done_ids:
        job=shell.jobs.pop(jid)
        if report:
            shell_write_out(f"[{jid}] Done: {job.description}\n")

