        return 0
    # foreground: give terminal and wait
    if shell.interactive and os.isatty(0):
        try: os.tcsetpgrp(0,job.pgid)
        except OSError as e:
            panic("src/process.rs:186:24",f"failed to tcsetpgrp: {errno_name(e.errno or 0)}",frames=21)
