        except ChildProcessError:
            break
        except InterruptedError:
            continue
        if wpid in remaining:
            if os.WIFSTOPPED(st):
                stopped_again=True; break
            statuses[wpid]=wait_status_to_code(st); remaining.discard(wpid)
