def call_function(shell, name, argv):
    body=shell.functions[name]
    frame=Frame(argv[1:])
    shell.frames.append(frame)
    old_heredoc=shell.heredoc_supported; shell.heredoc_supported=False
    try:
        st=run_command_dispatch(shell,body)
