def apply_redirects_in_parent(shell, redirects):
    """Prepare and apply, returning (prepared,saved) for restore_redirects_in_parent."""
    prep=prepare_redirects(shell,redirects)
    fds=set()
    for kind,fd,src in prep:
        fds.add(fd)
        if kind=='dup': fds.add(src)
