    # Reproduce pest errors for common failures.
    # Find '=' index
    eq=arg.find('=')
    if eq==-1:
        shell_error(f"nsh: alias:  --> 1:1\n  |\n1 | {arg}\n  | ^---\n  |\n  = expected alias")
        return 1
    name=arg[:eq]; body=arg[eq+1:]
