    if any(c in name for c in " \t\n\"'") or (name=="" and False):
        shell_error(f"nsh: alias:  --> 1:1\n  |\n1 | {arg}\n  | ^---\n  |\n  = expected alias")
        return 1
    if body=="":
        # expected body at position eq+2 (1-based after '=')
        col=eq+2
        shell_error(f"nsh: alias:  --> 1:{col}\n  |\n1 | {arg}\n  | {' '*(col-1)}^---\n  |\n  = expected body")
        return 1
    # body with a double quote: error expected EOI at quote position (only if '"' appears as a word-starting token after a space?)
    # Find a '"' preceded by a space (observed x=echo "a b")
    # Also any '"' in body seems problematic for their grammar; scan for '"'
    qi=body.find('"')
    if qi!=-1:
        col=eq+2+qi
        shell_error(f"nsh: alias:  --> 1:{col}\n  |\n1 | {arg}\n  | {' '*(col-1)}^---\n  |\n  = expected EOI")
        return 1
    shell.aliases[name]=body
