def parse_job_id_arg(shell,arg):
    # returns int job id or raises ValueError with message printed
    if not arg.startswith("%"):
        shell_error(f"nsh: invalid job id `{arg}'"); raise ExpansionError()
    rest=arg[1:]
    # Rust parse usize: optional + then digits
    t=rest[1:] if rest.startswith("+") else rest
    if not t.isdigit() or t=="":
        shell_error(f"nsh: invalid job id `{rest}'"); raise ExpansionError()
    try:
        v=int(t)
        if v>18446744073709551615: raise OverflowError()
    except OverflowError:
        shell_error(f"nsh: invalid job id `{rest}'"); raise ExpansionError()
    if v not in shell.jobs:
        shell_error(f"nsh: no such job `{v}'"); raise ExpansionError()
    return v

