    # Reap proc-subst children opportunistically (ignore)
    # Poll async jobs
    done_ids=[]
    for jid,job in list(shell.jobs.items()):
        all_done=True; any_stopped=False
        for pid in list(job.pids):
            try:
                wpid,st=os.waitpid(pid, os.WNOHANG|os.WUNTRACED)
            except ChildProcessError:
                continue
            if wpid==0:
                all_done=False; continue
            if os.WIFSTOPPED(st):
                any_stopped=True; all_done=False
            else:
                job.status=wait_status_to_code(st)
        if any_stopped:
            job.state="stopped"
        elif all_done:
            job.state="done"; done_ids.append(jid)
    for jid in done_ids:
        job=shell.jobs.pop(jid)
        if report:
            shell_write_out(f"[{jid}] Done: {job.description}\n")

