def highlight_line(shell,line):
    if line=="":
        return "\x1b[38;5;9m\x1b[0m"
    out=""; i=0; cmd_start=True
    n=len(line)
    while i<n:
        ch=line[i]
        if ch in " \t":
            out+=ch; i+=1; continue
        # separators
        if line.startswith("&&",i) or line.startswith("||",i):
            out+=f"\x1b[1m\x1b[38;5;12m{line[i:i+2]}\x1b[0m"; i+=2; cmd_start=True; continue
        if ch in ";|&":
            out+=f"\x1b[1m\x1b[38;5;12m{ch}\x1b[0m"; i+=1; cmd_start=True; continue
        if ch in "'\"":
            quote=ch; j=i+1
            while j<n:
                if quote=='"' and line[j]=='\\' and j+1<n: j+=2; continue
                if line[j]==quote: j+=1; break
                j+=1
            tok=line[i:j]
            out+=f"\x1b[38;5;14m{tok}\x1b[0m"; i=j; cmd_start=False; continue
        if line.startswith("$(",i):
            # find matching ) simple
            depth=0; j=i+1
            while j<n:
                if line[j]=='(': depth+=1
                elif line[j]==')':
                    depth-=1
                    if depth==0: break
                j+=1
            if j>=n:
                inner=line[i+2:]; close=""
            else:
                inner=line[i+2:j]; close=")"
            out+=f"\x1b[38;5;10m$(\x1b[0m"+highlight_line(shell,inner)
            if close: out+=f"\x1b[38;5;10m)\x1b[0m"
            i=j+1 if j<n else n; cmd_start=False; continue
        if ch=='$':
            m=re.match(r'\$(\{[^}]*\}?|[A-Za-z0-9_]+|[@*#?$!-])',line[i:])
            if m:
                tok=m.group(0); out+=f"\x1b[1m{tok}\x1b[0m"; i+=len(tok); cmd_start=False; continue
            out+=f"\x1b[1m$\x1b[0m"; i+=1; cmd_start=False; continue
        if ch=='`':
            j=line.find('`',i+1)
            if j==-1: j=n-1
            tok=line[i:j+1]; out+=tok; i=j+1; cmd_start=False; continue
        # plain word chunk up to delimiter or $ or quotes
        j=i
        while j<n and line[j] not in " \t;|&$'\"`":
            j+=1
        if j==i:
            out+=ch; i+=1; continue
        tok=line[i:j]
        if cmd_start:
            if tok in ("if","then","else","elif","fi"):
                out+=f"\x1b[1m{tok}\x1b[0m"; cmd_start=True
            else:
                m=re.match(r'^([A-Za-z0-9_]+=)(.*)$',tok,re.S)
                if m and m.group(2)!="" or (m and j<n):
                    out+=f"\x1b[38;5;9m{m.group(1)}\x1b[0m{m.group(2)}"; cmd_start=True
                else:
