                    out+=f"\x1b[38;5;{col}m{tok}\x1b[0m"; cmd_start=False
        else:
            if tok.startswith("-") and tok!="-":
                out+=f"\x1b[38;5;11m{tok}\x1b[0m"
            else:
                out+=tok
        i=j
    return out

