import termios
class KeyEvent:
    __slots__=("kind","ch","name","mods")
    def __init__(self,kind,ch="",name="",mods=""): self.kind=kind; self.ch=ch; self.name=name; self.mods=mods

class RawTerminal:
    def __init__(self,fd=0):
        self.fd=fd; self.orig=None
    def __enter__(self):
        self.orig=termios.tcgetattr(self.fd)
        raw=termios.tcgetattr(self.fd)
        # termion raw mode roughly
        raw[0] &= ~(termios.BRKINT|termios.ICRNL|termios.INPCK|termios.ISTRIP|termios.IXON)
        raw[1] &= ~(termios.OPOST)
        raw[2] |= termios.CS8
        raw[3] &= ~(termios.ECHO|termios.ICANON|termios.IEXTEN|termios.ISIG)
        raw[6][termios.VMIN]=1; raw[6][termios.VTIME]=0
        termios.tcsetattr(self.fd,termios.TCSANOW,raw)
        return self
    def __exit__(self,*a):
        if self.orig is not None:
            termios.tcsetattr(self.fd,termios.TCSANOW,self.orig)
    def restore(self):
        if self.orig is not None: termios.tcsetattr(self.fd,termios.TCSANOW,self.orig)
    def raw_again(self):
        self.__enter__()

