    kind='file'
    if token.startswith("$"):
        kind='var'
        pref=token.lstrip("${")
        names=list(shell.vars.keys())
        f=shell.get_local_frame()
        if f: names+=list(f.locals.keys())
        for nm in sorted(set(names)):
            candidates.append("$"+nm)
