    elif is_command:
        kind='command'
        candset=set()
        candset.update(BUILTINS); candset.update(shell.functions.keys()); candset.update(shell.aliases.keys())
        candset.update(["if","then","else","elif","fi","for","while","do","done","case","esac","function","local","return","break","continue","[[","]]","{","}","(",")"])
        for d in shell.lookup_path:
            dd=d if d else "."
            try:
                for e in os.scandir(dd):
                    try:
                        if e.is_file() and os.access(e.path,os.X_OK):
                            candset.add(e.name)
                    except Exception: pass
            except Exception: pass
        candidates=sorted(candset)
    else:
        kind='file'
        # Extract command name (first token of segment) for cd dir-only
        seg_start=max([before.rfind(c) for c in ";|&"]+[ -1])+1
        seg=line[seg_start:start].strip()
        cmdname=seg.split()[0] if seg.split() else ""
        dir_only = (cmdname=="cd")
        if "/" in token:
            dirpart,base=token.rsplit("/",1)
            dirpart_disp=dirpart+"/"
            fsdir=os.path.expanduser(dirpart) if dirpart else "."
            if dirpart.startswith("~"):
